import React from 'react';
import { Typography } from '@material-ui/core';
import StatTile from '../Common/StatTile';
import { circularLink, noticeboardLink, examLink } from './dashboardLinks';

// The last 30 days at a glance: how many circulars, notices and exams, each a summary card that opens its page.
// the three cards share the slot's height equally, label on the left and the figure on the right
const tileStyle = { flex: '1 1 0', minHeight: 0, padding: '0 16px' };

export default function CounterItems({ countData, history }) {
  // a plain click opens the page in this tab (same as the links these cards replaced)
  const open = link => () => history.push(link);
  return (
    <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <Typography variant="overline" style={{ fontWeight: 'bold', display: 'block', marginBottom: 6 }}>
        Last 30 days
      </Typography>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10, flex: 1, minHeight: 0 }}>
        <StatTile
          inline
          style={tileStyle}
          label="Circulars"
          value={countData?.circularCount || '--'}
          tone="neutral"
          onClick={open(circularLink())}
        />
        <StatTile
          inline
          style={tileStyle}
          label="Notice board"
          value={countData?.noticeboardCount || '--'}
          tone="info"
          onClick={open(noticeboardLink())}
        />
        <StatTile
          inline
          style={tileStyle}
          label="Exams"
          value={countData?.upcomingExamCount || '--'}
          tone="good"
          onClick={open(examLink())}
        />
      </div>
    </div>
  );
}
