import React from 'react';
import { Row, Col } from 'reactstrap';
import Avatar from '@material-ui/core/Avatar';
import EventIcon from '@material-ui/icons/Event';
import WbSunnyIcon from '@material-ui/icons/WbSunny';
import moment from 'moment';
import CommonTooltip from '../Common/CommonTooltip';
import colors from 'config/colors';
import { eventOrHolidayLink, goTo } from './dashboardLinks';

const EventOrHolidayItem = props => {
  const isEvent = props.carouselType === 'event';
  const iconColor = isEvent ? '#43a047' : '#f9a825';

  return (
    <Col
      lg="12"
      md="12"
      sm="12"
      style={{
        minHeight: 200,
        padding: '14px 18px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between',
      }}>
      <Row style={{ margin: 0 }}>
        <Avatar style={{ backgroundColor: `${iconColor}1a`, color: iconColor, marginRight: 14 }}>
          {isEvent ? <EventIcon /> : <WbSunnyIcon />}
        </Avatar>
        <Col style={{ padding: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 600 }}>{props.title}</div>
          {props.description && <div style={{ color: '#6b778a', fontSize: 12, marginTop: 2 }}>{props.description}</div>}
          <div style={{ marginTop: 6 }}>
            <CommonTooltip
              content={isEvent ? 'View events and other activities' : 'View holidays and other activities'}>
              <a
                style={{
                  color: colors.aTag,
                  fontWeight: 'bold',
                  fontSize: 12,
                  display: 'inline-block',
                  padding: '4px 10px',
                  borderRadius: 14,
                  backgroundColor: `${colors.aTag}14`,
                }}
                href={eventOrHolidayLink(props, props.carouselType)}
                onClick={goTo(props.history, eventOrHolidayLink(props, props.carouselType))}>
                {isEvent ? 'Go to events' : 'Go to holidays'}
              </a>
            </CommonTooltip>
          </div>
        </Col>
      </Row>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          marginTop: 14,
          paddingTop: 10,
          borderTop: '1px solid #f0f0f0',
          color: '#8b95a1',
          fontSize: 12,
        }}>
        <EventIcon style={{ fontSize: 14 }} />
        {moment(new Date(props.startDateTime)).format('LL')}
      </div>
    </Col>
  );
};

export default EventOrHolidayItem;
