import React from 'react';
import { Row, Col } from 'reactstrap';
import Avatar from '@material-ui/core/Avatar';
import EventIcon from '@material-ui/icons/Event';
import AssignmentTurnedInIcon from '@material-ui/icons/AssignmentTurnedIn';
import moment from 'moment';
import CommonTooltip from '../Common/CommonTooltip';
import colors from 'config/colors';
import { examLink, goTo } from './dashboardLinks';

const ExamItem = props => {
  const dur = props?.examDuration && moment.duration(props?.examDuration).asHours();
  const selDur = dur && moment.utc(dur * 3600 * 1000).format('HH:mm');
  const iconColor = '#fb8c00';

  return (
    <Col
      lg="12"
      md="12"
      sm="12"
      style={{
        minHeight: 200,
        padding: '14px 18px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between',
      }}>
      <Row style={{ margin: 0 }}>
        <Avatar style={{ backgroundColor: `${iconColor}1a`, color: iconColor, marginRight: 14 }}>
          <AssignmentTurnedInIcon />
        </Avatar>
        <Col style={{ padding: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 600 }}>{props.examTitle}</div>
          <div style={{ color: '#6b778a', fontSize: 12, marginTop: 2 }}>Total mark: {props.subjectTotalMark}</div>
          {!!selDur && (
            <div style={{ color: '#6b778a', fontSize: 12 }}>
              Duration: {Number(selDur.split(':')[0])} hours {Number(selDur.split(':')[1])} minutes
            </div>
          )}
          <div style={{ marginTop: 6 }}>
            <CommonTooltip content="View subject exams, date and hall">
              <a
                style={{
                  color: colors.aTag,
                  fontWeight: 'bold',
                  fontSize: 12,
                  display: 'inline-block',
                  padding: '4px 10px',
                  borderRadius: 14,
                  backgroundColor: `${colors.aTag}14`,
                }}
                href={examLink(props)}
                onClick={goTo(props.history, examLink(props))}>
                Go to Exams
              </a>
            </CommonTooltip>
          </div>
        </Col>
      </Row>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          marginTop: 14,
          paddingTop: 10,
          borderTop: '1px solid #f0f0f0',
          color: '#8b95a1',
          fontSize: 12,
        }}>
        <EventIcon style={{ fontSize: 14 }} />
        {moment(new Date(props.startDate)).format('LL')} – {moment(new Date(props.endDate)).format('LL')}
      </div>
    </Col>
  );
};

export default ExamItem;
