import {
  fetchAllSchoolsService,
  fetchSchoolService,
  fetchCircularCountForDashboardService,
  fetchNoticeboardCountForDashboardService,
  fetchTaskCountForDashboardService,
  fetchUpcomingCircularForNext3DaysService,
  fetchUpcomingEventForMonthService,
  fetchUpcomingExamCountForDashboardService,
  fetchUpcomingExamForMonthService,
  fetchUpcomingHolidayCountForDashboardService,
  fetchUpcomingHolidayForMonthService,
  fetchUpcomingMeetingForWeekService,
  fetchUpcomingNoticeboardForNext3DaysService,
  // dashboardAPIController,
} from 'actions/admin/schools';

import clsx from 'clsx';
import { withStyles } from '@material-ui/core/styles';
// import CssBaseline from '@material-ui/core/CssBaseline';
