import Paper from '@material-ui/core/Paper';
// import Link from '@material-ui/core/Link';
import {
  getCurrentYearBatchUtils,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  getLocalStore,
  getLoggedUserUtils,
  setGlobalSchoolUtils,
  setLocalStore,
} from '../../../utils/commonFunc';
import { fetchCurrentBatchByYearService } from '../../../actions/admin/batches';
import constants, { employeeStatic } from '../../../config/constants';
import { store } from '../../../index';
// import DashboardItem from "./DashboardItem";
import CountItems from './CountItems';
import CarouselStepper from './CarouselStepper';
import SchoolIcon from '@material-ui/icons/School';
import HomeIcon from '@material-ui/icons/Home';
