import AnnouncementIcon from '@material-ui/icons/Announcement';
import VideoCallIcon from '@material-ui/icons/VideoCall';
import AssignmentTurnedInIcon from '@material-ui/icons/AssignmentTurnedIn';
import EventIcon from '@material-ui/icons/Event';
import WbSunnyIcon from '@material-ui/icons/WbSunny';
import Avatar from '@material-ui/core/Avatar';
import Tab from '@material-ui/core/Tab';
import Tabs from '@material-ui/core/Tabs';
import { ScrollTabPanel } from '../Reports/index.js';
import { CommonLoader } from '../Common/Loader';
import ActivityList from '../Activities/ActivityList';
import NotificationsCard from './NotificationsCard';
import HolidaysReminderModal from './HolidaysReminderModal';
import WelcomeCard from './WelcomeCard';
import { fetchRecentActivitiesService } from 'actions/admin/activities';
import { fetchSchoolCommonConfigService } from 'actions/admin/config';
import colors from 'config/colors.js';

const drawerWidth = 240;
const styles = theme => ({
  root: {
    display: 'flex',
  },
  toolbar: {
    paddingRight: 24, // keep right padding when drawer closed
  },
  toolbarIcon: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'flex-end',
    padding: '0 8px',
    ...theme.mixins.toolbar,
  },
  menuButton: {
    marginRight: 36,
  },
  menuButtonHidden: {
    display: 'none',
  },
  title: {
    flexGrow: 1,
  },
  drawerPaper: {
    position: 'relative',
    whiteSpace: 'nowrap',
    width: drawerWidth,
    transition: theme.transitions.create('width', {
      easing: theme.transitions.easing.sharp,
      duration: theme.transitions.duration.enteringScreen,
    }),
  },
  drawerPaperClose: {
    overflowX: 'hidden',
    transition: theme.transitions.create('width', {
      easing: theme.transitions.easing.sharp,
      duration: theme.transitions.duration.leavingScreen,
    }),
    width: theme.spacing(7),
    [theme.breakpoints.up('sm')]: {
      width: theme.spacing(9),
    },
  },
  content: {
    flexGrow: 1,
    height: '100vh',
    overflow: 'auto',
  },
  container: {
    paddingTop: theme.spacing(1),
    paddingBottom: theme.spacing(1),
  },
  paper: {
    padding: theme.spacing(1),
    display: 'flex',
    overflow: 'auto',
    flexDirection: 'column',
  },
  fixedHeight: {
    height: 285,
  },
});

const tabList = [
  { tabIndex: 0, tabTitle: 'Upcomings', query: 'home', icon: <HomeIcon /> },
  { tabIndex: 1, tabTitle: 'Recent Activities', query: 'recent-activities', icon: <SchoolIcon /> },
];

let timer;
let timer1;
class Dashboard extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      schoolId: 0,
      schoolName: '',
      schoolCode: '',
      reloaded: false,
      activeTab: 0,
      dashboardFetching: false,
      recentActivitiesFetching: false,
      limit: 50,
    };
  }

  isLoading = (name, value) => {
    this.setState(prevState => ({ ...prevState, [name]: value }));
  };

  async componentDidMount() {
    const { search = null } = this.props?.location || {};
    if (search) {
      const cTab = tabList.find(dto => search.includes(dto.query));
      if (cTab) {
        this.toggleActivityTab(null, cTab.tabIndex);
      } else {
        this.toggleActivityTab(null, 0);
      }
    } else {
      this.toggleActivityTab(null, 0);
    }
    const globalSchool = getGlobalSchoolUtils();
    this.fetchSchoolCommonConfig(globalSchool?.schoolId);
    const userData = getLoggedUserUtils();
    if (!globalSchool) {
      if (userData?.userRole === constants.roles.SA) {
        const schools = await this.props.fetchAllSchools({ token: this.props.loggedUserToken });
        if (schools?.length) {
          this.updateGlobalSchool(schools?.[0]);
        }
      } else if (userData?.schoolId) {
        const school = await this.props.fetchSchool({
          schoolId: userData.schoolId,
          token: this.props.loggedUserToken,
        });
        this.updateGlobalSchool(school);
      } else {
        store.dispatch(
          showToast(
            'Sorry !!! No school has assigned to this account. Please contact School or Admin, We are logging you out...',
            'error'
          )
        );
        timer = setTimeout(() => {
          store.dispatch(logout());
        }, 6000);
      }
    } else {
      this.setState({
        schoolId: globalSchool?.schoolId,
      });
      this.fetchCurrentBatch(globalSchool?.schoolId);
      this.fetchDashboardData(globalSchool?.schoolId);
    }
  }

  fetchSchoolCommonConfig = async schoolId => {
    const { commonConfigList, loggedUserToken } = this.props;
    const { reloaded } = this.state;
    const commonConfigStore = getLocalStore('commonConfig');
    if (schoolId && (!commonConfigList?.length || !commonConfigStore?.length)) {
      const res = await this.props.fetchSchoolCommonConfig({
        schoolId,
        token: loggedUserToken,
      });
      setLocalStore('commonConfig', res);
      if (!commonConfigStore?.length && !reloaded) {
        this.setState(prevState => ({ ...prevState, reloaded: true }));
        // window?.location?.reload();
      }
    }
  };

  handleLimitChange = event => {
    const limit = event.target.value;
    this.setState(prevState => ({ ...prevState, limit }));
    this.fetchRecentActivities(limit);
  };

  fetchRecentActivities = async (limit = this.state.limit) => {
    this.isLoading('recentActivitiesFetching', true);
    const { loggedUserId, loggedUserToken } = this.props;
    const globalSchool = getGlobalSchoolUtils();
    await this.props.fetchRecentActivities({
      schoolId: globalSchool.schoolId,
      loggedUserId,
      token: loggedUserToken,
      limit,
    });
    this.isLoading('recentActivitiesFetching', false);
  };

  fetchDashboardData = async (schoolId = this.state.schoolId) => {
    clearTimeout(timer1);
    const { loggedUserToken, loggedUserId, loggedUserSchool } = this.props;
    const passData = { token: loggedUserToken, userId: loggedUserId, schoolId: schoolId || loggedUserSchool };
    this.props.fetchCircularCountForDashboard(passData);
    this.props.fetchNoticeboardCountForDashboard(passData);
    this.props.fetchTaskCountForDashboard(passData);
    this.props.fetchUpcomingHolidayCountForDashboard(passData);
    this.isLoading('dashboardFetching', true);
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId) {
      this.props.fetchUpcomingExamCountForDashboard({ ...passData, batchId });
      this.props.fetchUpcomingExamForMonth({ ...passData, batchId });
      this.props.fetchUpcomingMeetingForWeek({ ...passData, batchId });
    }
    await this.props.fetchUpcomingNoticeboardForNext3Days(passData);
    this.props.fetchUpcomingCircularForNext3Days(passData);
    await this.props.fetchUpcomingEventForMonth(passData);
    this.props.fetchUpcomingHolidayForMonth(passData);
    timer1 = setTimeout(() => {
      this.isLoading('dashboardFetching', false);
    }, 0);
  };

  fetchCurrentBatch = schoolId => {
    const { startYear, endYear } = getCurrentYearBatchUtils();
    const { batchId } = getGlobalCurrentBatchUtils();
    if (schoolId && !batchId) {
      store.dispatch(
        fetchCurrentBatchByYearService({
          token: this.props.loggedUserToken,
          schoolId,
          startYear,
          endYear,
        })
      );
    }
  };

  updateGlobalSchool = school => {
    if (school?.schoolId) {
      this.fetchDashboardData(school?.schoolId);
      setGlobalSchoolUtils(school);
      this.fetchCurrentBatch(school?.schoolId);
      this.setState({
        schoolId: school?.schoolId,
        schoolName: school?.schoolName,
        schoolCode: school?.schoolCode,
      });
    }
  };

  componentDidUpdate(prevProps) {
    const globalSchool = getGlobalSchoolUtils();
    if (prevProps.schools !== this.props.schools && globalSchool) {
      this.setState({
        schoolId: globalSchool.schoolId,
        schoolName: globalSchool.schoolName,
        schoolCode: globalSchool.schoolCode,
      });
      this.fetchCurrentBatch(globalSchool.schoolId);
    }
  }

  componentWillUnmount() {
    if (timer) {
      clearTimeout(timer);
    }
    // dashboardAPIController?.abort();
  }

  toggleActivityTab = (event, tabIndex) => {
    const { dashboardActiveTab } = this.props;
    if (tabIndex !== undefined && dashboardActiveTab !== tabIndex) {
      setCommonParam('dashboardActiveTab', tabIndex);
      if (tabIndex === 0) this.fetchDashboardData();
      if (tabIndex === 1) {
        this.fetchRecentActivities();
      }
      const cTab = tabList.find(dto => dto.tabIndex === tabIndex);
      if (cTab) {
        this.props.history.push(`${this.props.location.pathname}?${cTab.query}`);
      }
    }
  };

  render() {
    const { schoolName, dashboardFetching, recentActivitiesFetching, limit } = this.state;
    const globalSchool = getGlobalSchoolUtils();
    const loggedUser = getLoggedUserUtils();
    const { classes, dashboardData, dashboardActiveTab: activeTab, recentActivities } = this.props;
    const fixedHeightPaper = clsx(classes.paper, classes.fixedHeight);
    const roleLabel = {
      [constants.roles.SA]: 'Super admin',
      [constants.roles.admin]: 'School admin',
      [constants.roles.teacher]: employeeStatic,
      [constants.roles.guardian]: 'Guardian',
    }[loggedUser?.userRole];

    const countData = {
      circularCount: dashboardData?.circularCount?.circularCnt || 0,
      noticeboardCount: dashboardData?.noticeboardCount?.noticeBoardCnt || 0,
      taskCount: dashboardData?.taskCount?.taskCnt || 0,
      upcomingExamCount: dashboardData?.upcomingExamCount?.examCnt || 0,
    };

    const circularData = dashboardData?.upcomingCicularForNext3days;
    const noticeboardData = dashboardData?.upcomingNoticeboardForNext3days;
    const meetingData = dashboardData?.upcomingMeetingForWeek;
    const examData = dashboardData?.upcomingExamForMonth;
    const eventData = dashboardData?.upcomingEventForMonth;
    const holidayData = dashboardData?.upcomingHolidayForMonth;

    // const getCarouselDiv = (passData, heading) => {
    //   return passData?.length > 0 && (
    //      <Col sm={12} md={6} lg={6} className="mb-3">
    //       <Typography variant="overline">
    //         <b>{heading}</b>
    //       </Typography>
    //       <CarouselStepper carouselType="circular" carouselList={passData} {...this.props} />
    //     </Col>
    //   )
    // }

    // const upcomingData = {
    //   circular: getCarouselDiv(circularData, 'Upcoming Circulars'),
    //   noticeboard: getCarouselDiv(noticeboardData, 'Upcoming Noticeboards'),
    //   meeting: getCarouselDiv(meetingData, 'Upcoming Online classes'),
    //   exam: getCarouselDiv(examData, 'Upcoming Exams'),
    //   event: getCarouselDiv(eventData, 'Upcoming Events'),
    //   holiday: getCarouselDiv(holidayData, 'Upcoming Holidays'),
    // };

    const sectionTitle = (label, Icon, color) => (
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
        <Avatar style={{ backgroundColor: `${color}1a`, color, width: 28, height: 28 }}>
          <Icon style={{ fontSize: 16 }} />
        </Avatar>
        <span style={{ fontWeight: 'bold', fontSize: 14 }}>{label}</span>
      </div>
    );

    const upcomingData = {
      circular: circularData?.length > 0 && (
        <Col sm={12} md={6} lg={6} className="mb-3">
          {sectionTitle('Upcoming Circulars', NotificationsActiveIcon, '#e53935')}
          <CarouselStepper carouselType="circular" carouselList={circularData} {...this.props} />
        </Col>
      ),
      noticeboard: noticeboardData?.length > 0 && (
        <Col sm={12} md={6} lg={6} className="mb-3">
          {sectionTitle('Upcoming Noticeboards', AnnouncementIcon, '#00897b')}
          <CarouselStepper carouselType="noticeboard" carouselList={noticeboardData} {...this.props} />
        </Col>
      ),
      meeting: meetingData?.length > 0 && (
        <Col sm={12} md={6} lg={6} className="mb-3">
          {sectionTitle('Upcoming Online classes', VideoCallIcon, '#5e35b1')}
          <CarouselStepper carouselType="meeting" carouselList={meetingData} {...this.props} />
        </Col>
      ),
      exam: examData?.length > 0 && (
        <Col sm={12} md={6} lg={6} className="mb-3">
          {sectionTitle('Upcoming Exams', AssignmentTurnedInIcon, '#fb8c00')}
          <CarouselStepper carouselType="exam" carouselList={examData} {...this.props} />
        </Col>
      ),
      event: eventData?.length > 0 && (
        <Col sm={12} md={6} lg={6} className="mb-3">
          {sectionTitle('Upcoming Events', EventIcon, '#43a047')}
          <CarouselStepper carouselType="event" carouselList={eventData} {...this.props} />
        </Col>
      ),
      holiday: holidayData?.length > 0 && (
        <Col sm={12} md={6} lg={6} className="mb-3">
          {sectionTitle('Upcoming Holidays', WbSunnyIcon, '#f9a825')}
          <CarouselStepper carouselType="holiday" carouselList={holidayData} {...this.props} />
        </Col>
      ),
    };
    const upcomings = Object.values(upcomingData)?.length ? Object.values(upcomingData) : null;
    const renderFirstTab = dashboardFetching ? (
      <div style={{ textAlign: 'center', marginTop: 30 }}>
        <CommonLoader />
      </div>
    ) : upcomings?.filter(el => el)?.length > 0 ? (
      <Row>
        {upcomings.map((el, i) => (
          <React.Fragment key={i}>{el}</React.Fragment>
        ))}
      </Row>
    ) : (
      <div style={{ textAlign: 'center', fontWeight: 'bold', paddingTop: '50px', paddingBottom: '50px' }}>
        No upcoming events found
      </div>
    );

    return (
      <div className="content">
        {/* Material UI */}
        <Container maxWidth="lg" className={classes.container}>
          <Grid container spacing={2} direction="row">
            {/* Chart */}
            <Grid item xs={12} sm={8} md={8} lg={8}>
              <WelcomeCard
                userName={loggedUser?.fullName}
                schoolName={globalSchool?.schoolName || schoolName}
                roleLabel={roleLabel}
              />
            </Grid>
            {/* Recent Deposits */}
            <Grid item xs={12} sm={4} md={4} lg={4}>
              <Paper elevation={3} className={fixedHeightPaper} style={{ overflow: 'hidden' }}>
                <CountItems countData={countData} history={this.props.history} />
              </Paper>
            </Grid>
          </Grid>
          <NotificationsCard />
          {[constants.roles.SA, constants.roles.admin].includes(loggedUser?.userRole) && (
            <HolidaysReminderModal token={this.props.loggedUserToken} history={this.props.history} />
          )}
          <br />
          <Paper elevation={3} style={{ minHeight: '425px', backgroundColor: '#F4F6F8' }}>
            <Paper square elevation={3}>
              <Tabs
                value={activeTab}
                onChange={(e, tabIndex) => this.toggleActivityTab(e, tabIndex)}
                indicatorColor=""
                textColor="inherit"
                variant="fullWidth"
                scrollButtons="auto"
                aria-label="scrollable force tabs example">
                {tabList.map(item => {
                  return (
                    <Tab
                      key={item.tabIndex}
                      icon={item?.icon}
                      label={item.tabTitle}
                      style={{
                        fontWeight: 'bold',
                        color: activeTab === item.tabIndex ? colors.accent : '',
                        borderBottom: activeTab === item.tabIndex ? `3px solid ${colors.accent}` : '',
                      }}
                    />
                  );
                })}
              </Tabs>
            </Paper>
            <ScrollTabPanel value={activeTab} index={0} style={{ padding: 20 }}>
              {renderFirstTab}
            </ScrollTabPanel>
            <ScrollTabPanel value={activeTab} index={1} style={{ padding: 10 }}>
              <ActivityList
                recentActivitiesFetching={recentActivitiesFetching}
                activities={recentActivities}
                limit={limit}
                handleLimitChange={this.handleLimitChange}
              />
            </ScrollTabPanel>
          </Paper>
        </Container>
      </div>
    );
  }
}

export default withStyles(styles)(
  connect(
    state => ({
      loggedUserToken: state.auth.loggedUserToken,
      loggedUserId: state.auth.loggedUserId,
      loggedUserSchool: state?.auth?.loggedUserSchool,
      schools: state.schools.schoolList,
      dashboardData: state.schools.dashboardData,
      dashboardActiveTab: state.auth.dashboardActiveTab,
      recentActivities: state.activities.recentActivities,
      commonConfigList: state.config.commonConfigList,
    }),
    dispatch => ({
      fetchAllSchools: data => dispatch(fetchAllSchoolsService(data)),
      fetchSchool: data => dispatch(fetchSchoolService(data)),
      // Dashboard counts
      fetchCircularCountForDashboard: data => dispatch(fetchCircularCountForDashboardService(data)),
      fetchNoticeboardCountForDashboard: data => dispatch(fetchNoticeboardCountForDashboardService(data)),
      fetchTaskCountForDashboard: data => dispatch(fetchTaskCountForDashboardService(data)),
      fetchUpcomingExamCountForDashboard: data => dispatch(fetchUpcomingExamCountForDashboardService(data)),
      fetchUpcomingHolidayCountForDashboard: data => dispatch(fetchUpcomingHolidayCountForDashboardService(data)),
      // Dashboard data's
      fetchUpcomingNoticeboardForNext3Days: data => dispatch(fetchUpcomingNoticeboardForNext3DaysService(data)),
      fetchUpcomingCircularForNext3Days: data => dispatch(fetchUpcomingCircularForNext3DaysService(data)),
      fetchUpcomingEventForMonth: data => dispatch(fetchUpcomingEventForMonthService(data)),
      fetchUpcomingExamForMonth: data => dispatch(fetchUpcomingExamForMonthService(data)),
      fetchUpcomingHolidayForMonth: data => dispatch(fetchUpcomingHolidayForMonthService(data)),
      fetchUpcomingMeetingForWeek: data => dispatch(fetchUpcomingMeetingForWeekService(data)),
      fetchRecentActivities: data => dispatch(fetchRecentActivitiesService(data)),
      fetchSchoolCommonConfig: data => dispatch(fetchSchoolCommonConfigService(data)),
    })
  )(Dashboard)
);
