import React from 'react';
import { Row, Col } from 'reactstrap';
import Avatar from '@material-ui/core/Avatar';
import EventIcon from '@material-ui/icons/Event';
import VideoCallIcon from '@material-ui/icons/VideoCall';
import moment from 'moment';
import CommonTooltip from '../Common/CommonTooltip';
import colors from 'config/colors';

const MeetingItem = props => {
  let url = '';
  if (!props.meetupUrl.includes('http')) {
    url = `https://${props.meetupUrl}`;
  } else if (props.meetupUrl.includes('http') && !props.meetupUrl.includes('https')) {
    url = props.meetupUrl?.replace('http', 'https');
  } else {
    url = props.meetupUrl;
  }
  const iconColor = '#5e35b1';

  return (
    <Col
      lg="12"
      md="12"
      sm="12"
      style={{
        minHeight: 200,
        padding: '14px 18px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between',
      }}>
      <Row style={{ margin: 0 }}>
        <Avatar style={{ backgroundColor: `${iconColor}1a`, color: iconColor, marginRight: 14 }}>
          <VideoCallIcon />
        </Avatar>
        <Col style={{ padding: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 600 }}>{props.title}</div>
          {props.description && <div style={{ color: '#6b778a', fontSize: 12, marginTop: 2 }}>{props.description}</div>}
          <div style={{ marginTop: 6 }}>
            <CommonTooltip content="Join the online class by one click">
              <a
                style={{
                  color: colors.aTag,
                  fontWeight: 'bold',
                  fontSize: 12,
                  display: 'inline-block',
                  padding: '4px 10px',
                  borderRadius: 14,
                  backgroundColor: `${colors.aTag}14`,
                }}
                href={url}
                target="_blank"
                rel="noreferrer">
                Join here
              </a>
            </CommonTooltip>
          </div>
        </Col>
      </Row>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          marginTop: 14,
          paddingTop: 10,
          borderTop: '1px solid #f0f0f0',
          color: '#8b95a1',
          fontSize: 12,
        }}>
        <EventIcon style={{ fontSize: 14 }} />
        {moment(props?.meetupDate).format('MMM D, YYYY')} ({moment(props?.meetupStartTime).format('hh:mm A')} –{' '}
        {moment(props?.meetupEndTime).format('hh:mm A')})
      </div>
    </Col>
  );
};

export default MeetingItem;
