import React from 'react';
import { Row, Col } from 'reactstrap';
import Avatar from '@material-ui/core/Avatar';
import EventIcon from '@material-ui/icons/Event';
import NotificationsActiveIcon from '@material-ui/icons/NotificationsActive';
import AnnouncementIcon from '@material-ui/icons/Announcement';
import moment from 'moment';
import CommonTooltip from '../Common/CommonTooltip';
import colors from 'config/colors';
import { LinkifiedText } from '../Common/RichText';
import { circularLink, noticeboardLink, goTo } from './dashboardLinks';

const CircularOrNoticeboardItem = props => {
  const isCircular = props.carouselType === 'circular';
  const iconColor = isCircular ? '#e53935' : '#00897b';
  const url = isCircular ? circularLink(props) : noticeboardLink(props);

  return (
    <Col
      lg="12"
      md="12"
      sm="12"
      style={{
        minHeight: 200,
        padding: '14px 18px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between',
      }}>
      <Row style={{ margin: 0 }}>
        <Avatar style={{ backgroundColor: `${iconColor}1a`, color: iconColor, marginRight: 14 }}>
          {isCircular ? <NotificationsActiveIcon /> : <AnnouncementIcon />}
        </Avatar>
        <Col style={{ padding: 0 }}>
          <div
            style={{
              fontSize: 14,
              fontWeight: 600,
              lineHeight: 1.4,
              maxHeight: '2.8em',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
            }}>
            <LinkifiedText text={props.content} style={{ whiteSpace: 'normal' }} />
          </div>
          {props.subject && <div style={{ color: '#6b778a', fontSize: 12, marginTop: 2 }}>{props.subject}</div>}
          <div style={{ marginTop: 6 }}>
            <CommonTooltip content={`Open this ${isCircular ? 'circular' : 'notice'} in Teacher activities`}>
              <a
                style={{
                  color: colors.aTag,
                  fontWeight: 'bold',
                  fontSize: 12,
                  display: 'inline-block',
                  padding: '4px 10px',
                  borderRadius: 14,
                  backgroundColor: `${colors.aTag}14`,
                }}
                href={url}
                onClick={goTo(props.history, url)}>
                {isCircular ? 'Go to circular' : 'Go to notice board'}
              </a>
            </CommonTooltip>
          </div>
        </Col>
      </Row>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          marginTop: 14,
          paddingTop: 10,
          borderTop: '1px solid #f0f0f0',
          color: '#8b95a1',
          fontSize: 12,
        }}>
        <EventIcon style={{ fontSize: 14 }} />
        {moment(new Date(props.creationDateTime)).format('LL')}
      </div>
    </Col>
  );
};

export default CircularOrNoticeboardItem;
