import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { useHistory } from 'react-router-dom';
import SchoolIcon from '@material-ui/icons/School';
import PlaceIcon from '@material-ui/icons/Place';
import NotificationsIcon from '@material-ui/icons/Notifications';
import ChevronRightIcon from '@material-ui/icons/ChevronRight';
import colors from 'config/colors';
import { fetchUnreadNotificationCountApi } from 'actions/admin/notifications';

const decor = { position: 'absolute', borderRadius: '50%', background: 'rgba(255,255,255,0.07)' };

// The same welcome card as the mobile app's Home: a solid accent banner with the graduation-cap ring, WELCOME + role badge,
// the name, the school, and a tappable line for what needs attention (unread notifications).
const WelcomeCard = ({ userName, schoolName, roleLabel }) => {
  const history = useHistory();
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const [unread, setUnread] = useState(0);

  useEffect(() => {
    if (!loggedUserId || !loggedUserToken) return undefined;
    let cancelled = false;
    fetchUnreadNotificationCountApi({ userId: loggedUserId, token: loggedUserToken })
      .then(count => !cancelled && setUnread(count || 0))
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [loggedUserId, loggedUserToken]);

  if (!userName) return null;

  return (
    <div
      style={{
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        gap: 18,
        height: '100%',
        minHeight: 160,
        padding: '20px 24px',
        borderRadius: 14,
        background: colors.accent,
        overflow: 'hidden',
        color: '#fff',
        boxShadow: '0 3px 8px rgba(0,0,0,0.2)',
      }}>
      <div style={{ ...decor, width: 190, height: 190, top: -85, right: -50 }} />
      <div style={{ ...decor, width: 86, height: 86, top: 14, right: 90, background: 'rgba(255,255,255,0.05)' }} />
      <div style={{ ...decor, width: 120, height: 120, bottom: -60, left: -30 }} />
      <div
        style={{
          width: 72,
          height: 72,
          borderRadius: '50%',
          border: '1.5px solid rgba(255,255,255,0.35)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0,
          position: 'relative',
        }}>
        <div
          style={{
            width: 58,
            height: 58,
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.2)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}>
          <SchoolIcon style={{ fontSize: 28 }} />
        </div>
      </div>
      <div style={{ flex: 1, minWidth: 0, position: 'relative' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
          <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: 0.6, color: 'rgba(255,255,255,0.85)' }}>
            WELCOME
          </span>
          {!!roleLabel && (
            <span
              style={{
                background: 'rgba(255,255,255,0.22)',
                borderRadius: 8,
                padding: '2px 10px',
                fontSize: 10,
                fontWeight: 'bold',
                letterSpacing: 0.6,
              }}>
              {roleLabel.toUpperCase()}
            </span>
          )}
        </div>
        <div
          style={{
            fontSize: 24,
            fontWeight: 'bold',
            marginTop: 2,
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}>
          {userName}
        </div>
        {!!schoolName && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginTop: 2, color: 'rgba(255,255,255,0.9)' }}>
            <PlaceIcon style={{ fontSize: 15 }} />
            <span style={{ fontSize: 14, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {schoolName}
            </span>
          </div>
        )}
        {unread > 0 && (
          <div
            role="button"
            tabIndex={0}
            onClick={() => history.push('/admin/notifications')}
            onKeyDown={e => e.key === 'Enter' && history.push('/admin/notifications')}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              marginTop: 12,
              padding: '8px 12px',
              borderRadius: 8,
              background: 'rgba(255,255,255,0.2)',
              cursor: 'pointer',
              fontSize: 13.5,
              fontWeight: 600,
            }}>
            <NotificationsIcon style={{ fontSize: 16 }} />
            <span style={{ flex: 1 }}>
              You have {unread} unread notification{unread === 1 ? '' : 's'}
            </span>
            <ChevronRightIcon style={{ fontSize: 18, color: 'rgba(255,255,255,0.8)' }} />
          </div>
        )}
      </div>
    </div>
  );
};

export default WelcomeCard;
