import moment from 'moment';

// Where a dashboard card goes. Circulars, the notice board and events/holidays each have their own page; exams stay in
// Teacher Activities, which reads the tab from ?tab=. The query tells the page which item the card was showing.
const build = (path, params) => {
  const query = new URLSearchParams();
  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== '') query.set(key, value);
  });
  const queryString = query.toString();
  return queryString ? `${path}?${queryString}` : path;
};

const toDay = value => (value ? moment(new Date(value)).format('YYYY-MM-DD') : undefined);

export const circularLink = item => build('/admin/circulars', { circularId: item?.circularId });

export const noticeboardLink = item => build('/admin/notice-board', { noticeBoardId: item?.noticeBoardId });

export const examLink = item =>
  build('/admin/employee-activities', { tab: 'exams-marks', examId: item?.examTypeDetailId });

export const eventOrHolidayLink = (item, type) =>
  build('/admin/events-holidays', {
    type: type === 'holiday' ? 'HOLIDAY' : 'EVENT',
    date: toDay(item?.startDateTime),
  });

// Used as an <a> onClick: a plain click moves inside the app, ctrl/cmd-click still opens a new tab.
export const goTo = (history, url) => e => {
  if (e.metaKey || e.ctrlKey || e.shiftKey || e.button === 1) return;
  e.preventDefault();
  history.push(url);
};
