import React from 'react';
import moment from 'moment';
import Avatar from '@material-ui/core/Avatar';
import NotificationsIcon from '@material-ui/icons/Notifications';
import DraftsIcon from '@material-ui/icons/Drafts';
import colors from 'config/colors';

export const UNREAD_BG = '#F6EEFB';

// Row hover and the small-screen layout. Used by the Notifications page and the dashboard card.
export const notificationCss = `
  .notif-row { transition: background-color .12s ease; }
  .notif-row:hover { background: #F1E6F8 !important; }
  .notif-row:focus-visible { outline: 2px solid ${colors.accent}; outline-offset: -2px; }
  @media (max-width: 575px) {
    .notif-row { padding: 10px 12px 10px 8px !important; gap: 10px !important; }
    .notif-meta-by { display: none; }
  }
`;

const ROLE_LABELS = { ROLE_TEACHER: 'Teacher', ROLE_ADMIN: 'School admin', ROLE_DEAN: 'Dean' };

// One notification row, laid out like the mobile app's list: unread is tinted with an accent bar, a bold title and a
// dot; read is plain with lighter text. Used by the Notifications page and the dashboard card.
const NotificationItem = ({ item, unread, onClick, lines = 2 }) => {
  const by = ROLE_LABELS[item.userRole];
  return (
    <div
      className="notif-row"
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && onClick()}
      style={{
        display: 'flex',
        alignItems: 'flex-start',
        gap: 12,
        padding: '12px 16px 12px 12px',
        cursor: 'pointer',
        background: unread ? UNREAD_BG : '#fff',
        borderLeft: `4px solid ${unread ? colors.accent : 'transparent'}`,
        borderBottom: '1px solid #eee',
      }}>
      <Avatar
        style={{
          width: 34,
          height: 34,
          marginTop: 2,
          backgroundColor: unread ? `${colors.accent}1f` : '#f1f1f1',
          color: unread ? colors.accent : '#9a9a9a',
        }}>
        {unread ? <NotificationsIcon style={{ fontSize: 19 }} /> : <DraftsIcon style={{ fontSize: 19 }} />}
      </Avatar>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div
          style={{
            fontWeight: unread ? 'bold' : 'normal',
            color: unread ? '#2b2b2b' : '#6b6b6b',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
          }}>
          {item.title}
        </div>
        <div
          style={{
            fontSize: 13,
            color: unread ? '#4a4a4a' : '#9a9a9a',
            display: '-webkit-box',
            WebkitLineClamp: lines,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden',
            whiteSpace: 'pre-line',
          }}>
          {(item.textBody || '').trim()}
        </div>
        <div style={{ fontSize: 11, color: '#9a9a9a', marginTop: 3 }}>
          {moment(item.creationDateTime).format('MMM DD, YYYY hh:mm A')}
          {by && <span className="notif-meta-by">{`  ·  By ${by}`}</span>}
        </div>
      </div>
      {unread && (
        <span
          aria-label="Unread"
          style={{ width: 9, height: 9, borderRadius: '50%', background: colors.accent, marginTop: 8 }}
        />
      )}
    </div>
  );
};

export default NotificationItem;
