import React, { useEffect, useState } from 'react';
import axios from 'axios';
import moment from 'moment';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import constants from 'config/constants';
import { formResMessage, getGlobalSchoolUtils, getLocalStore, setLocalStore } from 'utils/commonFunc';

const REMIND_AFTER_DAYS = 7;
const snoozeKey = (schoolId, year) => `holidayReminderSnooze_${schoolId}_${year}`;

// Public holidays that fall on the same date every year; the ones that move with the calendar (Pongal, Diwali, Eid...) the
// admin adds on the Events and holidays page.
const FIXED_HOLIDAYS = [
  { month: 1, day: 26, title: 'Republic Day' },
  { month: 5, day: 1, title: 'May Day' },
  { month: 8, day: 15, title: 'Independence Day' },
  { month: 10, day: 2, title: 'Gandhi Jayanti' },
  { month: 12, day: 25, title: 'Christmas' },
];

// For the admin, once a year has no public holidays in the school's calendar: offers to add the fixed-date national ones
// right away or to go to the Events and holidays page, and otherwise reminds again after a week.
const HolidaysReminderModal = ({ token, history }) => {
  const [open, setOpen] = useState(false);
  const [adding, setAdding] = useState(false);
  const [error, setError] = useState('');
  const year = moment().year();
  const schoolId = getGlobalSchoolUtils()?.schoolId;

  useEffect(() => {
    if (!schoolId || !token) {
      return;
    }
    const snoozedUntil = getLocalStore(snoozeKey(schoolId, year));
    if (snoozedUntil && moment(snoozedUntil).isAfter(moment())) {
      return;
    }
    axios
      .get(
        `${constants.API_BASE_URL}/api/admin/activity-calendar/HOLIDAY/${year}?schoolId=${schoolId}`,
        constants.setHeader(token)
      )
      .then(res => setOpen(Array.isArray(res.data) && res.data.length === 0))
      .catch(() => setOpen(false));
  }, [schoolId, token, year]);

  const remindLater = () => {
    setLocalStore(snoozeKey(schoolId, year), moment().add(REMIND_AFTER_DAYS, 'days').toISOString());
    setOpen(false);
  };

  const goToHolidays = () => {
    setOpen(false);
    history.push('/admin/events-holidays');
  };

  const addFixed = async () => {
    setAdding(true);
    setError('');
    try {
      await Promise.all(
        FIXED_HOLIDAYS.map(holiday => {
          const date = moment({ year, month: holiday.month - 1, day: holiday.day });
          return axios.post(
            `${constants.API_BASE_URL}/api/admin/activity-calendar`,
            {
              title: holiday.title,
              description: `${holiday.title} - public holiday`,
              activityType: 'HOLIDAY',
              startDateTime: date.valueOf(),
              endDateTime: date.valueOf(),
              currentYear: `${year}`,
              school: { schoolId },
            },
            constants.setHeader(token)
          );
        })
      );
      setOpen(false);
      history.push('/admin/events-holidays');
    } catch (err) {
      setError(formResMessage(err));
    } finally {
      setAdding(false);
    }
  };

  return (
    <Modal isOpen={open} centered>
      <ModalHeader>PUBLIC HOLIDAYS FOR {year}</ModalHeader>
      <ModalBody>
        <p>
          No public holidays are added for {year} yet. Parents, teachers and the app calendar show only the holidays you
          add here.
        </p>
        <p style={{ marginBottom: 0 }}>
          <b>Add now</b> puts the fixed-date holidays ({FIXED_HOLIDAYS.map(item => item.title).join(', ')}) into the
          calendar. Add the rest, like Pongal or Diwali, from the Events and holidays page.
        </p>
        {!!error && <p className="err-msg mt-2">{error}</p>}
      </ModalBody>
      <ModalFooter>
        <CustomButton type="button" loading={adding} disabled={adding} onClick={addFixed} name="Add now" />
        <CustomButton
          className="ml-2"
          type="button"
          color="default"
          disabled={adding}
          onClick={goToHolidays}
          name="Go to holidays"
        />
        <CustomButton
          className="ml-2"
          type="button"
          color="default"
          disabled={adding}
          onClick={remindLater}
          name="Remind me later"
        />
      </ModalFooter>
    </Modal>
  );
};

export default HolidaysReminderModal;
