import React, { useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import { useHistory } from 'react-router-dom';
import Paper from '@material-ui/core/Paper';
import Avatar from '@material-ui/core/Avatar';
import NotificationsActiveIcon from '@material-ui/icons/NotificationsActive';
import ChevronRightIcon from '@material-ui/icons/ChevronRight';
import colors from 'config/colors';
import { fetchReceivedNotificationsApi, fetchUnreadNotificationCountApi } from 'actions/admin/notifications';
import { CommonLoader } from '../Common/Loader';
import { useContainWheel } from 'utils/useContainWheel';
import NotificationItem, { notificationCss } from '../Notifications/NotificationItem';
import EmptyState from 'views/admin/Common/EmptyState';

const LIMIT = 10;

// The dashboard's notifications card: the last 10 notifications the user received, unread ones highlighted, and a link
// to the full Notifications page (Announcements) for the rest.
const NotificationsCard = () => {
  const history = useHistory();
  const loggedUserId = useSelector(state => state.auth.loggedUserId);
  const loggedUserToken = useSelector(state => state.auth.loggedUserToken);
  const [items, setItems] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (!loggedUserId || !loggedUserToken) return;
    let cancelled = false;
    setIsLoading(true);
    Promise.all([
      fetchReceivedNotificationsApi({ userId: loggedUserId, page: 1, size: LIMIT, token: loggedUserToken }),
      fetchUnreadNotificationCountApi({ userId: loggedUserId, token: loggedUserToken }).catch(() => 0),
    ])
      .then(([list, count]) => {
        if (cancelled) return;
        setItems(list.slice(0, LIMIT));
        setUnreadCount(count);
      })
      .catch(() => !cancelled && setItems([]))
      .finally(() => !cancelled && setIsLoading(false));
    return () => {
      cancelled = true;
    };
  }, [loggedUserId, loggedUserToken]);

  const openAll = () => history.push('/admin/notifications');

  const listRef = useRef(null);
  useContainWheel(listRef);

  return (
    <Paper elevation={3} style={{ marginTop: 16, overflow: 'hidden', borderRadius: 12 }}>
      <style>{notificationCss}</style>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 16px', background: '#fff' }}>
        <Avatar style={{ backgroundColor: `${colors.accent}1a`, color: colors.accent, width: 32, height: 32 }}>
          <NotificationsActiveIcon style={{ fontSize: 18 }} />
        </Avatar>
        <b style={{ fontSize: 15, whiteSpace: 'nowrap' }}>Notifications</b>
        {unreadCount > 0 && (
          <span
            style={{
              background: colors.accent,
              color: '#fff',
              borderRadius: 10,
              padding: '1px 8px',
              fontSize: 11,
              fontWeight: 'bold',
              whiteSpace: 'nowrap',
            }}>
            {unreadCount} new
          </span>
        )}
        <a
          href="/admin/notifications"
          onClick={e => {
            e.preventDefault();
            openAll();
          }}
          style={{
            marginLeft: 'auto',
            fontSize: 13,
            fontWeight: 'bold',
            color: colors.accent,
            display: 'flex',
            whiteSpace: 'nowrap',
          }}>
          View more
          <ChevronRightIcon style={{ fontSize: 18 }} />
        </a>
      </div>
      <div
        ref={listRef}
        style={{ maxHeight: 380, overflowY: 'auto', overscrollBehavior: 'contain', borderTop: '1px solid #eee' }}>
        {isLoading ? (
          <div style={{ padding: 24, textAlign: 'center' }}>
            <CommonLoader />
          </div>
        ) : items.length ? (
          items.map(item => (
            <NotificationItem
              key={item.notificationId}
              item={item}
              unread={item.readStatus === 'UNREAD'}
              onClick={openAll}
              lines={1}
            />
          ))
        ) : (
          <EmptyState compact bare icon="far fa-bell" title="No notifications yet" />
        )}
      </div>
    </Paper>
  );
};

export default NotificationsCard;
