import React from 'react';
import { makeStyles, useTheme } from '@material-ui/core/styles';
import MobileStepper from '@material-ui/core/MobileStepper';
import Button from '@material-ui/core/Button';
import KeyboardArrowLeft from '@material-ui/icons/KeyboardArrowLeft';
import KeyboardArrowRight from '@material-ui/icons/KeyboardArrowRight';
import SwipeableViews from 'react-swipeable-views';
// import { autoPlay } from 'react-swipeable-views-utils';
import CircularOrNoticeboardItem from './CircularOrNoticeboardItem';
import EventOrHolidayItem from './EventOrHolidayItem';
import ExamItem from './ExamItem';
import MeetingItem from './MeetingItem';
import { Paper } from '@material-ui/core';

// const AutoPlaySwipeableViews = autoPlay(SwipeableViews);

const useStyles = makeStyles(theme => ({
  root: {
    maxWidth: 'auto',
    flexGrow: 1,
    border: '1px solid #eef0f2',
    borderRadius: 10,
    overflow: 'hidden',
    boxShadow: '0 1px 4px rgba(0,0,0,0.05)',
  },
  header: {
    display: 'flex',
    alignItems: 'center',
    height: 50,
    paddingLeft: theme.spacing(4),
    backgroundColor: theme.palette.background.default,
  },
  img: {
    height: 255,
    display: 'block',
    maxWidth: 400,
    overflow: 'hidden',
    width: '100%',
  },
}));

function SwipeableTextMobileStepper(props) {
  const { carouselType, carouselList } = props;
  const classes = useStyles();
  const theme = useTheme();
  const [activeStep, setActiveStep] = React.useState(0);
  const maxSteps = carouselList?.length;

  const handleNext = () => {
    setActiveStep(prevActiveStep => prevActiveStep + 1);
  };

  const handleBack = () => {
    setActiveStep(prevActiveStep => prevActiveStep - 1);
  };

  const handleStepChange = step => {
    setActiveStep(step);
  };

  const getTypeCarousel = item => {
    return {
      circular: <CircularOrNoticeboardItem {...item} {...props} />,
      noticeboard: <CircularOrNoticeboardItem {...item} {...props} />,
      meeting: <MeetingItem {...item} iconAndColor="nc-globe text-primary" {...props} />,
      exam: <ExamItem {...item} iconAndColor="nc-globe text-primary" {...props} />,
      event: <EventOrHolidayItem {...item} iconAndColor="nc-globe text-primary" {...props} />,
      holiday: <EventOrHolidayItem {...item} iconAndColor="nc-globe text-primary" {...props} />,
    };
  };

  return (
    <Paper elevation={0} className={classes.root}>
      <SwipeableViews
        axis={theme.direction === 'rtl' ? 'x-reverse' : 'x'}
        index={activeStep}
        onChangeIndex={handleStepChange}
        enableMouseEvents>
        {carouselList?.map((step, index) => (
          <div key={index} style={{ maxHeight: 225 }}>
            {Math.abs(activeStep - index) <= 2 ? (
              <div style={{ minHeight: 225, marginBottom: 1, backgroundColor: 'white', border: '1px solid white' }}>
                {getTypeCarousel({ ...step, carouselType })[carouselType]}
              </div>
            ) : null}
          </div>
        ))}
      </SwipeableViews>
      <MobileStepper
        variant="dots"
        steps={maxSteps}
        position="static"
        activeStep={activeStep}
        nextButton={
          <Button size="small" onClick={handleNext} disabled={activeStep === maxSteps - 1}>
            {theme.direction === 'rtl' ? <KeyboardArrowLeft /> : <KeyboardArrowRight />}
          </Button>
        }
        backButton={
          <Button size="small" onClick={handleBack} disabled={activeStep === 0}>
            {theme.direction === 'rtl' ? <KeyboardArrowRight /> : <KeyboardArrowLeft />}
          </Button>
        }
      />
    </Paper>
  );
}

export default SwipeableTextMobileStepper;
